from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Parity (0 or 1) of each element of xs, computed in parallel with a
    thread pool. The result is in input order, regardless of worker count."""
    with ThreadPoolExecutor() as ex:
        return list(ex.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([1, 2, 3, 4, 5]) == [1, 0, 1, 0, 1]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative_and_zero() -> None:
    assert parities([-3, -2, -1, 0]) == [1, 0, 1, 0]


def test_parities_large_ints() -> None:
    big = 10**30
    assert parities([big, big + 1]) == [0, 1]


def test_parities_preserves_order_large_input() -> None:
    xs = list(range(1000))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_does_not_mutate_input() -> None:
    xs = [3, 4, 5]
    parities(xs)
    assert xs == [3, 4, 5]


def test_parities_order_independent_of_worker_count(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import time

    import __main__  # noqa: F401

    xs = list(range(200, 0, -1))
    expected = [x % 2 for x in xs]
    results: list[list[int]] = []
    original = ThreadPoolExecutor
    for workers in (1, 2, 8, 32):

        def make(*args: object, _w: int = workers, **kwargs: object) -> ThreadPoolExecutor:
            return original(max_workers=_w)

        monkeypatch.setattr(f"{__name__}.ThreadPoolExecutor", make)
        results.append(parities(xs))
        time.sleep(0)
    assert all(r == expected for r in results)

